pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an array length (as uint256) and a single amount value and one recipient address
    // we use an array length so fuzzer explores varying sizes; we will construct arrays accordingly
    function testFuzz_property(uint256 lenRaw, uint256 vRaw, address recipient) public {
        // keep length within reasonable bounds but wide
        uint256 len = bound(lenRaw, 1, 5); // require _tos.length > 0 in contract

        // construct arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = recipient;
            // keep v such that the contract's internal require about multiplication holds for non-zero values
            // the reference contract allows v[i] == 0 OR ((v*1e18)/v == 1e18), which is true for any v that doesn't overflow
            // we'll choose vRaw directly; bound it to avoid trivial overflow in multiplication in solidity uint256 (but solidity wraps, contract's check is robust)
            vals[i] = vRaw;
        }

        // call and capture whether call completed (did not revert) and, if so, what it returned
        bool ok;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: for every admissible input where the call does not revert (ok == true), the reference contract returns true.
        // We assert that: if call succeeded, its return value is true. This holds for the reference implementation for all inputs,
        // and fails for the mutant (which can return false on successful calls), so the fuzz will find such an input.
        if (ok) {
            assertTrue(ret);
        } else {
            // if call reverted, we do not assert on return value; still acceptable for universal property
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: two small arrays encoded via a seed uint256 and a second uint256 controlling lengths,
    // plus an address to be used as one of the recipients (the fuzzer can vary it, though EOAs always succeed on low-level call).
    // We keep assumptions wide: length between 1 and 4, and values arbitrary uints.
    function testFuzz_property(uint256 seed, uint256 lenBound, address recip) public {
        // Keep length in a small, wide range so loop executes and arrays are non-empty
        uint256 len = bound(lenBound, 1, 4);

        // Build arrays deterministically from seed so fuzzer explores space
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);
        for (uint i = 0; i < len; i++) {
            // derive recipient addresses from supplied recip and seed so fuzzer can vary recipients
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(recip, seed, i)))));
            // derive values; include zero and large values — leave full uint domain
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, recip)));
        }

        // The reference contract requires msg.sender to be a specific hardcoded address.
        // vm.prank lets us call from that address so the call does not revert due to sender check.
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(requiredSender);

        // Call and capture whether the call returned successfully and the boolean return value.
        // Use low-level call to capture the returned bool for the external call; but Foundry supports direct call return too.
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, consider that as failing admissible domain; set ok to false
            ok = false;
        }

        // General property: for the correct contract, any non-reverting invocation of transfer returns true.
        // We assert that the observed return (ok) is true. The mutant that returns false for successful calls
        // will cause this assertion to fail for some admissible inputs where the call does not revert.
        assertTrue(ok);
    }
}

