pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: arrays and a target address; fuzzer will vary them
    function testFuzz_property(address target, uint256[] memory amounts) public {
        // admissible domain: non-empty amounts and target not zero
        vm.assume(target != address(0));
        vm.assume(amounts.length > 0);

        // Build a tos array with the fuzzed single target repeated to match amounts length
        address[] memory tos = new address[](amounts.length);
        for (uint i = 0; i < amounts.length; i++) tos[i] = target;

        // The contract requires msg.sender to be a specific address; make the call as that address
        address privileged = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(privileged);

        // Call and capture whether it completed (didn't revert) and its return value via try/catch
        bool ok;
        bool ret;
        try c.transfer(tos, amounts) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General property: for all admissible inputs where the call does not revert, reference C returns true.
        // So assert that if the call completed, its returned value is true.
        // This will hold for the reference contract and fail for the mutant (which returns false on completion).
        assertTrue(!ok || ret);
    }
}

