// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an array length and two uint arrays/addresses are hard to fuzz directly in Foundry
    // we will fuzz a single address and two uint256 values and build arrays from them to keep test simple
    function testFuzz_property(address to, uint256 v0, uint256 v1) public {
        // admissible domain:
        // - msg.sender must be the hard-coded allowed sender in C
        // - _tos.length > 0 (we'll use length 1 or 2)
        // - amount values must satisfy the contract's internal multiplicative check when non-zero
        address allowedSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

        // build arrays: choose length 1 to keep wide domain
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v0;

        // The contract has a require that either v[i]==0 or (v[i]*1e18)/v[i] == 1e18.
        // That holds for any v[i] that does not overflow when multiplied by 1e18 and is non-zero.
        // To keep domain wide and avoid overflow, bound v0 to a safe range when non-zero.
        // Allow v0==0 freely.
        if (v0 != 0) {
            // bound to avoid overflow in v0 * 1e18: max = type(uint256).max / 1e18
            v0 = bound(v0, 1, type(uint256).max / 1000000000000000000);
            vals[0] = v0;
        }

        // Ensure we invoke as the allowed sender
        vm.prank(allowedSender);

        // Call and capture whether the call completes (does not revert) and capture return value using try/catch
        bool completed = false;
        bool ret = false;
        try c.transfer(tos, vals) returns (bool r) {
            completed = true;
            ret = r;
        } catch {
            completed = false;
        }

        // General rule: when the call completes, the reference C always returns true.
        // So assert that if it completed then the returned boolean is true.
        // This will hold for the reference contract for all admissible inputs and fail for the mutant
        // which flips the returned boolean.
        if (completed) {
            assertTrue(ret);
        } else {
            // If it reverted, nothing to assert about return value; still valid universal property
            assertTrue(true);
        }
    }
}
